// Albers equal-area conic projection for the contiguous United States
// (standard parallels 29.5°N and 45.5°N, central meridian 96°W, origin 37.5°N),
// the same parameters USGS and the US Census use for national maps.
const RAD = Math.PI / 180;
const P1 = 29.5 * RAD, P2 = 45.5 * RAD, LAT0 = 37.5 * RAD, LON0 = -96 * RAD;
const N = (Math.sin(P1) + Math.sin(P2)) / 2;
const C = Math.cos(P1) ** 2 + 2 * N * Math.sin(P1);
const RHO0 = Math.sqrt(C - 2 * N * Math.sin(LAT0)) / N;
export const EARTH_RADIUS_KM = 6371.0088;

// Unit-sphere projection, y pointing north.
export function albers(lon, lat) {
  const rho = Math.sqrt(C - 2 * N * Math.sin(lat * RAD)) / N;
  const theta = N * (lon * RAD - LON0);
  return [rho * Math.sin(theta), RHO0 - rho * Math.cos(theta)];
}

// Fit of the contiguous US into the 850 × 420 map viewBox. Generated by tools/build-basemap.mjs.
export const FIT = {k: 771.3918, x: 431.0833, y: 209.6181};

// Longitude/latitude (degrees) → map viewBox coordinates.
export function project(lon, lat) {
  const [x, y] = albers(lon, lat);
  return [FIT.x + FIT.k * x, FIT.y - FIT.k * y];
}

// Points along the great circle between two lon/lat positions (spherical interpolation).
export function greatCircle([lon1, lat1], [lon2, lat2], steps = 32) {
  const toVec = (lon, lat) => [Math.cos(lat * RAD) * Math.cos(lon * RAD), Math.cos(lat * RAD) * Math.sin(lon * RAD), Math.sin(lat * RAD)];
  const a = toVec(lon1, lat1), b = toVec(lon2, lat2);
  const d = Math.acos(Math.max(-1, Math.min(1, a[0] * b[0] + a[1] * b[1] + a[2] * b[2])));
  if (d < 1e-9) return [[lon1, lat1], [lon2, lat2]];
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, s1 = Math.sin((1 - t) * d) / Math.sin(d), s2 = Math.sin(t * d) / Math.sin(d);
    const v = [s1 * a[0] + s2 * b[0], s1 * a[1] + s2 * b[1], s1 * a[2] + s2 * b[2]];
    pts.push([Math.atan2(v[1], v[0]) / RAD, Math.atan2(v[2], Math.hypot(v[0], v[1])) / RAD]);
  }
  return pts;
}

// Great-circle distance in km.
export function distanceKm([lon1, lat1], [lon2, lat2]) {
  const h = Math.sin((lat2 - lat1) * RAD / 2) ** 2 + Math.cos(lat1 * RAD) * Math.cos(lat2 * RAD) * Math.sin((lon2 - lon1) * RAD / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(h));
}

// Keep the detailed US basemap for domestic scenarios; fit geographically positioned
// airports outside that region into a coordinate overview without inventing land outlines.
export function fitNetwork(points){
 const extended=points.some(p=>p.lon < -125||p.lon > -66||p.lat < 24||p.lat > 50);
 if(!extended)return {extended:false,project,graticule:''};
 const lat0=points.reduce((s,p)=>s+p.lat,0)/points.length,cos=Math.cos(lat0*RAD);
 const raw=(lon,lat)=>[lon*cos,-lat];
 const coords=points.map(p=>raw(p.lon,p.lat));
 const x0=Math.min(...coords.map(p=>p[0])),x1=Math.max(...coords.map(p=>p[0]));
 const y0=Math.min(...coords.map(p=>p[1])),y1=Math.max(...coords.map(p=>p[1]));
 const k=Math.min(710/Math.max(1,x1-x0),290/Math.max(1,y1-y0));
 const fitted=(lon,lat)=>{const [x,y]=raw(lon,lat);return [405+k*(x-(x0+x1)/2),195+k*(y-(y0+y1)/2)];};
 const path=(a,b)=>{const p=fitted(...a),q=fitted(...b);return `M${p[0]},${p[1]}L${q[0]},${q[1]}`;};
 let graticule='';
 for(let lon=-180;lon<=180;lon+=20)graticule+=path([lon,15],[lon,75]);
 for(let lat=20;lat<=70;lat+=10)graticule+=path([-180,lat],[180,lat]);
 return {extended:true,project:fitted,graticule};
}
